import csv
import io
import json
import os
import sys
import unicodedata


def norm_id(value):
    return str(value).strip().casefold()


def norm_text(value):
    chars = []
    for ch in str(value).casefold():
        category = unicodedata.category(ch)
        chars.append(ch if category[0] == "L" or category == "Nd" else " ")
    return " ".join("".join(chars).split())


def parse_revision(value):
    return int(str(value).strip())


def read_csv(text):
    lines = text.split("\n")
    directives = {}
    index = 0
    while index < len(lines) and (lines[index].startswith("#") or not lines[index].strip()):
        line = lines[index]
        if line.startswith("#") and ":" in line:
            name, value = line[1:].split(":", 1)
            directives[name.strip().lower()] = value.strip()
        index += 1
    rows = csv.reader(io.StringIO("\n".join(lines[index:]), newline=""))
    header = None
    records = []
    for row in rows:
        if not row or not any(cell.strip() for cell in row):
            continue
        if header is None:
            header = [cell.strip().lower() for cell in row]
            continue
        data = dict(zip(header, row))
        ranks = {}
        for name, cell in data.items():
            if name.startswith("rank") and name[4:].isdigit():
                number = int(name[4:])
                marks = []
                if cell is not None and cell != "":
                    for part in cell.split("|"):
                        if part.startswith("WI:"):
                            marks.append(("wi", part[3:]))
                        elif part.strip():
                            marks.append(("id", part.strip()))
                ranks[number] = marks
        records.append((data.get("ballot", "").strip(), data.get("contest", "").strip(), ranks))
    return directives, records


def read_jsonl(text):
    directives = None
    records = []
    for line in text.split("\n"):
        if not line.strip():
            continue
        obj = json.loads(line)
        if directives is None:
            directives = {k.lower(): v for k, v in obj.items()}
            continue
        ranks = {}
        for mark in obj.get("marks", []):
            number = int(mark["rank"])
            bucket = ranks.setdefault(number, [])
            if mark.get("write_in") is not None:
                bucket.append(("wi", mark["write_in"]))
            elif mark.get("candidate") is not None:
                bucket.append(("id", str(mark["candidate"]).strip()))
        records.append((obj.get("ballot"), obj.get("contest"), ranks))
    return directives or {}, records


def load_records(cvr_dir):
    batches = {}
    for name in sorted(os.listdir(cvr_dir)):
        path = os.path.join(cvr_dir, name)
        if not os.path.isfile(path):
            continue
        if not (name.endswith(".csv") or name.endswith(".jsonl")):
            continue
        with open(path, encoding="utf-8-sig", newline="") as handle:
            text = handle.read().replace("\r\n", "\n")
        directives, records = read_csv(text) if name.endswith(".csv") else read_jsonl(text)
        batch = str(directives.get("batch", "")).strip()
        revision = parse_revision(directives.get("revision", 0))
        status = str(directives.get("status", "final")).strip().lower()
        current = batches.get(batch)
        if current is None or revision > current[0]:
            batches[batch] = (revision, status, records)
    result = []
    for revision, status, records in batches.values():
        if status != "void":
            result.extend(records)
    return result


class Contest:
    def __init__(self, definition):
        self.id = definition["id"]
        self.max_ranks = definition["max_ranks"]
        self.names = {}
        self.withdrawn = set()
        self.continuing_start = []
        for cand in definition.get("candidates", []):
            key = norm_id(cand["id"])
            self.names[key] = cand["id"]
            if cand.get("status") == "withdrawn":
                self.withdrawn.add(key)
            else:
                self.continuing_start.append(key)
        self.writeins = {}
        for wi in definition.get("write_ins", []):
            key = norm_id(wi["id"])
            self.names[key] = wi["id"]
            self.continuing_start.append(key)
            for text in [wi["name"]] + list(wi.get("aliases", [])):
                self.writeins[norm_text(text)] = key
        self.lot = [norm_id(x) for x in definition.get("lot_order", [])]
        self.ballots = []

    def read_ballot(self, ranks):
        seen = set()
        entries = []
        for number in range(1, self.max_ranks + 1):
            marks = set()
            for kind, value in ranks.get(number, []):
                if kind == "wi":
                    target = self.writeins.get(norm_text(value))
                    if target is not None:
                        marks.add(target)
                else:
                    marks.add(norm_id(value))
            if not marks:
                entries.append(("skip", None))
                continue
            marks -= self.withdrawn
            if not marks:
                entries.append(("pass", None))
                continue
            fresh = marks - seen
            seen |= marks
            if not fresh:
                entries.append(("skip", None))
            elif len(fresh) == 1:
                entries.append(("choice", next(iter(fresh))))
            else:
                entries.append(("over", None))
        return entries

    def count_for(self, entries, continuing):
        for index, (kind, value) in enumerate(entries):
            if kind == "choice":
                if value in continuing:
                    return value
            elif kind == "over":
                return None
            elif kind == "skip":
                if index + 1 >= len(entries) or entries[index + 1][0] == "skip":
                    return None
        return None

    def run(self):
        ballots = [self.read_ballot(ranks) for ranks in self.ballots]
        continuing = list(self.continuing_start)
        history = []
        rounds = []
        winner = None
        while True:
            votes = {cand: 0 for cand in continuing}
            active = 0
            for entries in ballots:
                target = self.count_for(entries, votes)
                if target is not None:
                    votes[target] += 1
                    active += 1
            history.append(votes)
            entry = {
                "round": len(history),
                "tallies": {self.names[c]: votes[c] for c in continuing},
                "exhausted": len(ballots) - active,
                "eliminated": [],
            }
            rounds.append(entry)
            if active == 0:
                break
            leader = next((c for c in continuing if votes[c] * 2 > active), None)
            if leader is None and len(continuing) == 1:
                leader = continuing[0]
            if leader is not None:
                winner = self.names[leader]
                break
            zeros = [c for c in continuing if votes[c] == 0]
            if zeros:
                out = zeros
            else:
                out = [self.pick_loser(continuing, history)]
            entry["eliminated"] = sorted(self.names[c] for c in out)
            continuing = [c for c in continuing if c not in out]
        return {"contest": self.id, "ballots": len(ballots), "winner": winner, "rounds": rounds}

    def pick_loser(self, continuing, history):
        last = history[-1]
        low = min(last[c] for c in continuing)
        tied = [c for c in continuing if last[c] == low]
        for past in range(len(history) - 2, -1, -1):
            if len(tied) == 1:
                break
            low = min(history[past][c] for c in tied)
            tied = [c for c in tied if history[past][c] == low]
        if len(tied) == 1:
            return tied[0]
        return max(tied, key=lambda c: self.lot.index(c) if c in self.lot else -1)


def main():
    input_dir, output_file = sys.argv[1], sys.argv[2]
    with open(os.path.join(input_dir, "election.json"), encoding="utf-8") as handle:
        election = json.load(handle)
    contests = [Contest(definition) for definition in election["contests"]]
    by_id = {contest.id: contest for contest in contests}
    for _ballot, contest_id, ranks in load_records(os.path.join(input_dir, "cvr")):
        if contest_id in by_id:
            by_id[contest_id].ballots.append(ranks)
    result = {"election": election["election"], "contests": [c.run() for c in contests]}
    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump(result, handle, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
